import assert from 'node:assert/strict';
import {DatabaseSync} from 'node:sqlite';
import fs from 'node:fs';
import {handleApi} from '../worker/account-api.js';

const sql=new DatabaseSync(':memory:');sql.exec('PRAGMA foreign_keys=ON');
for(const f of fs.readdirSync(new URL('../drizzle/',import.meta.url)).filter(f=>f.endsWith('.sql')).sort())sql.exec(fs.readFileSync(new URL('../drizzle/'+f,import.meta.url),'utf8'));
let beforeBatch=null,failBatchAt=-1;
class Statement{constructor(query,args=[]){this.query=query;this.args=args;}bind(...args){return new Statement(this.query,args);}async first(){return sql.prepare(this.query).get(...this.args)||null;}async all(){return {results:sql.prepare(this.query).all(...this.args)};}async run(){return {meta:{changes:sql.prepare(this.query).run(...this.args).changes}};}}
let chain=Promise.resolve();
const DB={prepare:q=>new Statement(q),batch(statements){const next=chain.then(()=>{if(beforeBatch){const hook=beforeBatch;beforeBatch=null;hook();}sql.exec('BEGIN');try{const out=statements.map((s,i)=>{if(i===failBatchAt){failBatchAt=-1;throw Error('Injected storage failure');}return {meta:{changes:sql.prepare(s.query).run(...s.args).changes}};});sql.exec('COMMIT');return out;}catch(e){sql.exec('ROLLBACK');throw e;}});chain=next.catch(()=>{});return next;}};
async function api(user,path,method='GET',body){const r=await handleApi(new Request('https://test.chatgpt.site/api'+path,{method,headers:{...(user?{'oai-authenticated-user-id':user,'oai-authenticated-user-email':user+'@example.test','X-UK-Account-ID':user}:{}),...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined}),{DB});return {status:r.status,...await r.json()};}
for(const user of ['owner','source','editor','viewer','outsider'])assert.equal((await api(user,'/account')).status,200);
const clone=x=>structuredClone(x),strip=x=>Array.isArray(x)?x.map(strip):x&&typeof x==='object'?Object.fromEntries(Object.entries(x).filter(([k])=>!['privateNotes','private_notes'].includes(k)).map(([k,v])=>[k,strip(v)])):x;
const readDoc=user=>{const r=sql.prepare('SELECT * FROM documents WHERE user_id=?').get(user);return {revision:r.revision,state:JSON.parse(r.state)};};
let serial=0;
function setup({local=false}={}){
 const id='automation-'+(++serial),foreign='enrolled-request-'+serial;
 const gang=(name)=>({id:'same',name,edition:'N26',credits:100,reputation:1,stash:[],tactics:[],logs:[],fighters:[{id:'fighter',name:'Fighter',xp:5,status:'Active',equipment:[],injuries:[],effects:[],xpHistory:[],notes:'Keep fighter notes',privateNotes:'secret fighter'}],notes:'Keep gang notes',privateNotes:'secret gang'});
 const host=gang('Host'),source=gang('Source'),campaign={id,name:'Campaign '+serial,edition:'N26',members:[{id:'m-host',gangId:'same',player:'Host'},...(!local?[{id:'m-source',gangId:foreign,player:'Source',ownerId:'source',userId:'source',sourceGangId:'same',enrollmentRequestId:'request-'+serial}]:[])],currentCycle:1,phase:'Active',territories:[],sessions:[],battles:[],activity:[],map:{objects:[{id:'shape',x:1.25}]},privateNotes:'secret campaign'};
 for(const [user,state]of Object.entries({owner:{gangs:[host],campaigns:[clone(campaign)],view:'campaign'},source:{gangs:[source],campaigns:[]},editor:{gangs:[],campaigns:[]},viewer:{gangs:[],campaigns:[]},outsider:{gangs:[],campaigns:[]}}))sql.prepare('INSERT INTO documents(user_id,revision,state,updated_at) VALUES(?,1,?,?) ON CONFLICT(user_id) DO UPDATE SET revision=1,state=excluded.state').run(user,JSON.stringify(state),'2026-10-31');
 const snapshot={campaign:strip(campaign),gangs:[strip(host),...(!local?[{...strip(source),id:foreign,sourceGangId:'same',sourceOwnerId:'source',remoteOwnerId:'source',remoteReadOnly:true,enrollmentRequestId:'request-'+serial}]:[])]};
 if(!local){sql.prepare('INSERT INTO shared_campaigns(id,owner_id,name,snapshot,revision,updated_at) VALUES(?,?,?,?,1,?)').run(id,'owner',campaign.name,JSON.stringify(snapshot),'2026-10-31');for(const [user,role]of [['source','viewer'],['editor','editor'],['viewer','viewer']])sql.prepare('INSERT INTO campaign_access(campaign_id,user_id,role,status,invited_at) VALUES(?,?,?,\'accepted\',?)').run(id,user,role,'2026-10-31');sql.prepare("INSERT INTO campaign_join_requests(id,campaign_id,user_id,gang_id,gang_name,gang_snapshot,source_revision,message,status,created_at,updated_at) VALUES(?,?,?,?,?,?,1,'','approved',?,?)").run('request-'+serial,id,'source','same','Source',JSON.stringify(strip(source)),'2026-10-31','2026-10-31');}
 return {id,foreign,snapshot};
}
function request(f,key,mutate){const before=clone(f.snapshot),after=clone(before);mutate(after);return {operationKey:key,label:'Test settlement',documentRevision:readDoc('owner').revision,expectedCampaignRevision:sql.prepare('SELECT revision FROM shared_campaigns WHERE id=?').get(f.id)?.revision,before,after};}
const send=(user,f,body)=>api(user,'/campaigns/'+f.id+'/automation','POST',body);
const current=f=>JSON.parse(sql.prepare('SELECT snapshot FROM shared_campaigns WHERE id=?').get(f.id).snapshot);
const counts=id=>sql.prepare('SELECT COUNT(*) n FROM campaign_automation_operations WHERE campaign_id=?').get(id).n;

// A cross-owner settlement is rejected atomically; each player changes their own original.
let f=setup(),body=request(f,'battle-1',s=>{s.campaign.currentCycle=2;s.gangs[0].credits=110;s.gangs[1].credits=125;s.gangs[1].fighters[0].xp=6;s.gangs[1].fighters[0].xpHistory.push({id:'xp-event',amount:1});});
assert.equal((await send(null,f,body)).status,401);assert.equal((await send('viewer',f,{...body,documentRevision:1})).status,403);assert.equal((await send('outsider',f,body)).status,403);
assert.equal((await send('owner',f,body)).status,403);assert.equal(readDoc('owner').state.gangs[0].credits,100);assert.equal(readDoc('source').state.gangs[0].credits,100);assert.equal(counts(f.id),0);body=request(f,'battle-own',s=>{s.campaign.currentCycle=2;s.gangs[0].credits=110;s.gangs[0].fighters[0].xp=6;s.gangs[0].fighters[0].xpHistory.push({id:'xp-event',amount:1});});let result=await send('owner',f,body);assert.equal(result.status,200,result.error);const receipt=result.receipt.id;assert.equal(readDoc('owner').state.gangs[0].credits,110);assert.equal(readDoc('source').state.gangs[0].credits,100);assert.equal(readDoc('owner').state.gangs[0].fighters[0].xp,6);assert.equal(readDoc('owner').state.campaigns[0].currentCycle,2);assert.equal(current(f).gangs[0].credits,110);assert.equal(current(f).gangs[1].credits,100);assert.equal(readDoc('source').state.gangs[0].fighters[0].privateNotes,'secret fighter');assert(!JSON.stringify(result.receipt).includes('secret'));assert.equal(counts(f.id),1);
const oldRevisions=[readDoc('owner').revision,readDoc('source').revision];assert.equal((await send('owner',f,body)).replayed,true);assert.deepEqual([readDoc('owner').revision,readDoc('source').revision],oldRevisions);assert.equal((await send('owner',f,{...body,after:{...body.after,campaign:{...body.after.campaign,currentCycle:3}}})).status,409);
// Undo compares only changed fields and preserves an unrelated later edit.
const sourceDoc=readDoc('owner');sourceDoc.state.gangs[0].fighters[0].notes='Unrelated later note';assert.equal((await api('owner','/document','PUT',{revision:sourceDoc.revision,state:sourceDoc.state})).status,200);
result=await api('owner','/campaigns/'+f.id+'/automation/'+receipt+'/reverse','POST',{documentRevision:readDoc('owner').revision});assert.equal(result.status,200,result.error);assert(result.receipt.reversedAt);assert.equal(readDoc('owner').state.gangs[0].credits,100);assert.equal(readDoc('owner').state.gangs[0].fighters[0].xp,5);assert.equal(readDoc('source').state.gangs[0].credits,100);assert.equal(readDoc('source').state.gangs[0].fighters[0].xp,5);assert.equal(readDoc('owner').state.gangs[0].fighters[0].notes,'Unrelated later note');assert.equal(readDoc('source').state.gangs[0].fighters[0].privateNotes,'secret fighter');assert.equal(readDoc('owner').state.campaigns[0].currentCycle,1);assert.equal((await api('owner','/campaigns/'+f.id+'/automation/'+receipt+'/reverse','POST',{documentRevision:1})).replayed,true);
assert.equal((await api('viewer','/campaigns/'+f.id+'/automation')).receipts.length,1);

// Editors have game-operation permission; a roster role label does not grant access.
f=setup();body=request(f,'editor-award',s=>{s.gangs[1].reputation=2;});body.documentRevision=1;assert.equal((await send('editor',f,body)).status,403);assert.equal(readDoc('source').state.gangs[0].reputation,1);body=request(f,'editor-cycle-blocked',s=>{s.campaign.currentCycle=2;});assert.equal((await send('editor',f,body)).status,403);body=request(f,'editor-common-fact',s=>{s.campaign.battles.push({id:'editor-match',name:'Shared match',status:'Played',winner:'same',winners:['same'],participants:[{gangId:'same',role:'attacker'},{gangId:f.foreign,role:'defender'}]});});assert.equal((await send('editor',f,body)).status,200);assert.equal(current(f).campaign.currentCycle,1);assert.equal(current(f).campaign.battles.length,1);
f=setup();body=request(f,'forged-owner',s=>{s.gangs[1].sourceOwnerId='outsider';s.gangs[1].credits=999;});assert.equal((await send('owner',f,body)).status,403);assert.equal(readDoc('source').state.gangs[0].credits,100);assert.equal(counts(f.id),0);
body=request(f,'forged-identity',s=>{s.campaign.members[1].ownerId='outsider';});assert.equal((await send('owner',f,body)).status,400);
body=request(f,'private-edit',s=>{s.gangs[0].privateNotes='Stolen';s.gangs[0].credits=120;});assert.equal((await send('owner',f,body)).status,400);
body=request(f,'unrelated-edit',s=>{s.gangs[0].notes='Overwrite authored text';});assert.equal((await send('owner',f,body)).status,400);
body=request(f,'outside-reference',s=>{s.campaign.sessions.push({id:'s',name:'Bad',participants:[{id:'p',gangId:'outsider'}]});});assert.equal((await send('owner',f,body)).status,400);
body=request(f,'invalid-value',s=>{s.gangs[0].credits=-1;});assert.equal((await send('owner',f,body)).status,400);assert.equal(counts(f.id),0);

// A later field conflict prevents undo rather than blindly restoring a whole old document.
f=setup();body=request(f,'conflicting-undo',s=>{s.gangs[0].credits=120;});result=await send('owner',f,body);assert.equal(result.status,200);const operation=result.receipt.id,changed=readDoc('owner');changed.state.gangs[0].credits=121;await api('owner','/document','PUT',{revision:changed.revision,state:changed.state});assert.equal((await api('owner','/campaigns/'+f.id+'/automation/'+operation+'/reverse','POST',{documentRevision:readDoc('owner').revision})).status,409);assert.equal(readDoc('owner').state.gangs[0].credits,121);assert.equal((await api('owner','/campaigns/'+f.id+'/automation')).receipts[0].reversedAt,null);

// CAS guards run inside the D1 transaction, including participant withdrawal and permission changes.
f=setup();body=request(f,'source-race',s=>{s.gangs[0].credits=110;s.gangs[0].credits=130;});beforeBatch=()=>sql.prepare('UPDATE documents SET revision=revision+1 WHERE user_id=?').run('owner');assert.equal((await send('owner',f,body)).status,409);assert.equal(readDoc('owner').state.gangs[0].credits,100);assert.equal(readDoc('source').state.gangs[0].credits,100);assert.equal(current(f).gangs[0].credits,100);assert.equal(current(f).gangs[1].credits,100);assert.equal(counts(f.id),0);assert.equal(sql.prepare('SELECT COUNT(*) n FROM campaign_automation_assertions').get().n,0);
f=setup();sql.prepare("UPDATE campaign_access SET role='arbitrator' WHERE campaign_id=? AND user_id='editor'").run(f.id);body=request(f,'revoked-arbitrator',s=>{s.campaign.currentCycle=2;});beforeBatch=()=>sql.prepare("UPDATE campaign_access SET role='viewer' WHERE campaign_id=? AND user_id='editor'").run(f.id);assert.equal((await send('editor',f,body)).status,409);assert.equal(readDoc('source').state.gangs[0].credits,100);assert.equal(counts(f.id),0);
f=setup();body=request(f,'removed-source',s=>{s.gangs[1].credits=130;});body.documentRevision=readDoc('source').revision;beforeBatch=()=>sql.prepare("UPDATE campaign_join_requests SET status='removed' WHERE campaign_id=?").run(f.id);assert.equal((await send('source',f,body)).status,409);assert.equal(readDoc('source').state.gangs[0].credits,100);
f=setup();body=request(f,'storage-rollback',s=>{s.gangs[0].credits=110;s.gangs[0].credits=130;});failBatchAt=2;assert.equal((await send('owner',f,body)).status,500);assert.equal(readDoc('owner').state.gangs[0].credits,100);assert.equal(readDoc('source').state.gangs[0].credits,100);assert.equal(counts(f.id),0);

// Same-key races return the same receipt, while distinct conflicting operations apply only once.
f=setup();body=request(f,'same-request-race',s=>{s.gangs[0].credits=110;});let races=await Promise.all([send('owner',f,body),send('owner',f,body)]);assert.deepEqual(races.map(r=>r.status),[200,200]);assert.equal(races[0].receipt.id,races[1].receipt.id);assert.equal(counts(f.id),1);assert.equal(readDoc('owner').state.gangs[0].credits,110);
f=setup();body=request(f,'different-race-a',s=>{s.gangs[0].credits=110;});races=await Promise.all([send('owner',f,body),send('owner',f,{...body,operationKey:'different-race-b'})]);assert.deepEqual(races.map(r=>r.status).sort(),[200,409]);assert.equal(counts(f.id),1);assert.equal(readDoc('owner').state.gangs[0].credits,110);

// Unpublished owner campaigns stay private and can use the same receipt/undo mechanism.
f=setup({local:true});body=request(f,'local-cycle',s=>{s.campaign.currentCycle=2;s.gangs[0].credits=105;});result=await send('owner',f,body);assert.equal(result.status,200,result.error);assert.equal(readDoc('owner').state.gangs[0].credits,105);assert.equal(readDoc('owner').state.campaigns[0].currentCycle,2);assert.equal(sql.prepare('SELECT id FROM shared_campaigns WHERE id=?').get(f.id),undefined);assert.equal((await api('owner','/campaigns/'+f.id+'/automation/'+result.receipt.id+'/reverse','POST',{documentRevision:readDoc('owner').revision})).status,200);

// Only the actual enrolled source owner may acknowledge or accept an existing capture/offer.
f=setup();const ownerState=readDoc('owner'),capture={id:'capture',campaignId:f.id,releasedAt:null,rosterApplied:false,target:{sourceId:'same',ownerId:'source',fighterId:'fighter',name:'Fighter',gangName:'Source'},ransomOffer:{id:'offer',amount:40,status:'offered',offeredBy:'owner',sourceOwnerId:'source',offeredAt:'2026-10-31'}};ownerState.state.gangs[0].campaignCaptives=[capture];sql.prepare('UPDATE documents SET state=? WHERE user_id=?').run(JSON.stringify(ownerState.state),'owner');let snap=current(f);snap.gangs[0].campaignCaptives=[clone(capture)];sql.prepare('UPDATE shared_campaigns SET snapshot=? WHERE id=?').run(JSON.stringify(snap),f.id);
const consent=(user,decision,key,extra={})=>api(user,'/campaigns/'+f.id+'/automation/consent','POST',{operationKey:key,documentRevision:readDoc(user).revision,holderId:'same',recordId:'capture',decision,offerId:'offer',...extra});
assert.equal((await consent('viewer','acknowledge','forged-consent')).status,403);assert.equal((await consent('owner','acknowledge','wrong-owner')).status,403);result=await consent('source','acknowledge','source-ack');assert.equal(result.status,200,result.error);assert.equal(readDoc('source').state.gangs[0].fighters[0].status,'Captured');assert.equal(readDoc('owner').state.gangs[0].campaignCaptives[0].sourceAcknowledgedBy,'source');
const acceptedBody={operationKey:'ransom-accept',documentRevision:readDoc('source').revision,holderId:'same',recordId:'capture',decision:'accept',offerId:'offer',amount:1,sourceOwnerId:'outsider'};result=await api('source','/campaigns/'+f.id+'/automation/consent','POST',acceptedBody);assert.equal(result.status,200,result.error);assert.equal(readDoc('source').state.gangs[0].credits,60);assert.equal(readDoc('owner').state.gangs[0].credits,140);assert.equal(readDoc('source').state.gangs[0].fighters[0].status,'Active');assert.equal(readDoc('source').state.gangs[0].fighters[0].privateNotes,'secret fighter');assert.equal(readDoc('owner').state.gangs[0].campaignCaptives[0].ransomOffer.acceptedBy,'source');assert.equal((await api('source','/campaigns/'+f.id+'/automation/consent','POST',acceptedBody)).replayed,true);assert.equal(readDoc('source').state.gangs[0].credits,60);
body=request(f,'viewer-generic',state=>{state.gangs[0].credits=999;});body.documentRevision=readDoc('source').revision;assert.equal((await send('source',f,body)).status,403);

// An idempotency receipt cannot be replayed by a different person as source-owner consent.
assert.equal((await api('viewer','/campaigns/'+f.id+'/automation/consent','POST',acceptedBody)).status,403);
// Removed models restore their private material on undo; public receipts never expose it.
f=setup();body=request(f,'remove-model',s=>{s.gangs[1].fighters=[];});body.documentRevision=readDoc('source').revision;result=await send('source',f,body);assert.equal(result.status,200,result.error);assert.equal(readDoc('source').state.gangs[0].fighters.length,0);assert(!JSON.stringify(result.receipt).includes('secret fighter'));assert.equal((await api('source','/campaigns/'+f.id+'/automation/'+result.receipt.id+'/reverse','POST',{documentRevision:readDoc('source').revision})).status,200);assert.equal(readDoc('source').state.gangs[0].fighters[0].privateNotes,'secret fighter');

// Declining an existing offer never transfers money or changes the captured fighter.
f=setup();let holderDoc=readDoc('owner'),targetDoc=readDoc('source');const makeCapture=()=>({id:'capture',campaignId:f.id,releasedAt:null,rosterApplied:true,beforeState:{status:'Active'},target:{sourceId:'same',ownerId:'source',fighterId:'fighter'},ransomOffer:{id:'offer',amount:40,status:'offered',offeredBy:'owner',sourceOwnerId:'source'}});
holderDoc.state.gangs[0].campaignCaptives=[makeCapture()];Object.assign(targetDoc.state.gangs[0].fighters[0],{status:'Captured',captured:true,capturedBy:'same',captured_by_gang_id:'same',campaignCaptureId:'capture'});sql.prepare('UPDATE documents SET state=? WHERE user_id=?').run(JSON.stringify(holderDoc.state),'owner');sql.prepare('UPDATE documents SET state=? WHERE user_id=?').run(JSON.stringify(targetDoc.state),'source');snap=current(f);snap.gangs[0].campaignCaptives=[makeCapture()];Object.assign(snap.gangs[1].fighters[0],{status:'Captured',captured:true,capturedBy:'same',captured_by_gang_id:'same',campaignCaptureId:'capture'});sql.prepare('UPDATE shared_campaigns SET snapshot=? WHERE id=?').run(JSON.stringify(snap),f.id);
assert.equal((await consent('source','decline','declined-offer')).status,200);assert.equal(readDoc('source').state.gangs[0].credits,100);assert.equal(readDoc('source').state.gangs[0].fighters[0].status,'Captured');assert.equal(readDoc('owner').state.gangs[0].campaignCaptives[0].ransomOffer.status,'declined');

// Rescue evidence must pre-exist this operation; an arbitrary result inserted alongside a release is rejected.
f.snapshot=current(f);body=request(f,'fake-rescue',s=>{const r=s.gangs[0].campaignCaptives[0];r.releasedAt='2026-10-31';r.releaseMethod='rescue';r.releaseBattleId='rescue-battle';s.campaign.battles.push({id:'rescue-battle',status:'Played',winners:[f.foreign],participants:[{gangId:'same'},{gangId:f.foreign}],rescueResults:[{captureId:'capture',fighterId:'fighter',rescued:true}]});});assert.equal((await send('owner',f,body)).status,409);assert.equal(readDoc('source').state.gangs[0].fighters[0].status,'Captured');
snap=current(f);snap.campaign.battles=clone(body.after.campaign.battles);sql.prepare('UPDATE shared_campaigns SET snapshot=? WHERE id=?').run(JSON.stringify(snap),f.id);f.snapshot=current(f);body=request(f,'verified-rescue',s=>{const r=s.gangs[0].campaignCaptives[0];r.releasedAt='2026-10-31';r.releaseMethod='rescue';r.releaseBattleId='rescue-battle';});assert.equal((await send('owner',f,body)).status,200);assert.equal(readDoc('source').state.gangs[0].fighters[0].status,'Captured','The holder never edits the opponent’s roster');f.snapshot=current(f);body=request(f,'source-rescue-result',s=>{s.gangs[1].fighters[0].status='Active';for(const key of ['captured','capturedBy','captured_by_gang_id','campaignCaptureId'])delete s.gangs[1].fighters[0][key];});body.documentRevision=readDoc('source').revision;assert.equal((await send('source',f,body)).status,200);assert.equal(readDoc('source').state.gangs[0].fighters[0].status,'Active');

// Unrelated archived participants do not invalidate current operations.
f=setup();snap=current(f);snap.campaign.battles.push({id:'old-battle',status:'Played',participants:[{gangId:'removed-long-ago'}],winner:'removed-long-ago'});sql.prepare('UPDATE shared_campaigns SET snapshot=? WHERE id=?').run(JSON.stringify(snap),f.id);f.snapshot=current(f);body=request(f,'keep-history',s=>{s.gangs[0].credits=105;});assert.equal((await send('owner',f,body)).status,200);assert.equal(current(f).campaign.battles[0].winner,'removed-long-ago');

// A quick join may append only the campaign owner's real original, then reverse that append.
f=setup();let hostDocument=readDoc('owner');hostDocument.state.gangs.push({...clone(hostDocument.state.gangs[0]),id:'spare',name:'Spare owned gang'});sql.prepare('UPDATE documents SET state=? WHERE user_id=?').run(JSON.stringify(hostDocument.state),'owner');body=request(f,'quick-join',s=>{s.campaign.members.push({id:'spare-member',gangId:'spare',player:'Owner',role:'Player',allegianceId:''});});assert.equal((await send('editor',f,body)).status,403);result=await send('owner',f,body);assert.equal(result.status,200,result.error);assert(current(f).campaign.members.some(m=>m.gangId==='spare'));assert(current(f).gangs.some(g=>g.id==='spare'));assert.equal((await api('owner','/campaigns/'+f.id+'/automation/'+result.receipt.id+'/reverse','POST',{documentRevision:readDoc('owner').revision})).status,200);assert(!current(f).campaign.members.some(m=>m.gangId==='spare'));assert(!current(f).gangs.some(g=>g.id==='spare'));assert(readDoc('owner').state.gangs.some(g=>g.id==='spare'));
// Previously registered owner gangs can outpace the published participant snapshot.
function pendingOwnedQuickBattle({foreignCopy=false}={}){const fixture=setup(),doc=readDoc('owner'),member={id:'pending-member',gangId:'pending-owned',player:'Owner',role:'Player',allegianceId:''},gang={...clone(doc.state.gangs[0]),id:member.gangId,name:'Pending owned gang',...(foreignCopy?{remoteReadOnly:true,remoteOwnerId:'source'}:{})};doc.state.gangs.push(gang);doc.state.campaigns[0].members.push(member);Object.assign(doc.state.campaigns[0],{remoteOwnerId:'owner',remoteCampaignId:fixture.id,remoteRole:'owner',remoteRevision:1});sql.prepare('UPDATE documents SET state=? WHERE user_id=?').run(JSON.stringify(doc.state),'owner');const operation=request(fixture,'pending-quick-battle',state=>{state.campaign.sessions.push({id:'pending-session',stage:'pre-battle',status:'Active',challenger:'same',opponent:member.gangId,participants:[{id:'qa',gangId:'same'},{id:'qb',gangId:member.gangId}]});});operation.before.campaign.members=strip(doc.state.campaigns[0].members);operation.after.campaign.members=strip(doc.state.campaigns[0].members);return {fixture,operation};}
let pendingQuick=pendingOwnedQuickBattle();assert.equal((await send('editor',pendingQuick.fixture,pendingQuick.operation)).status,400,'An editor cannot reconcile the owner’s unpublished membership');result=await send('owner',pendingQuick.fixture,pendingQuick.operation);assert.equal(result.status,200,result.error);assert.equal(current(pendingQuick.fixture).campaign.members.filter(m=>m.gangId==='pending-owned').length,1);assert(current(pendingQuick.fixture).gangs.some(g=>g.id==='pending-owned'));assert.equal(current(pendingQuick.fixture).campaign.sessions[0].opponent,'pending-owned');assert.equal(readDoc('owner').state.campaigns[0].sessions.length,1);assert.equal(readDoc('owner').state.campaigns[0].remoteRevision,2);assert.equal((await send('owner',pendingQuick.fixture,pendingQuick.operation)).replayed,true);assert.equal(counts(pendingQuick.fixture.id),1);assert.equal((await api('owner','/campaigns/'+pendingQuick.fixture.id+'/automation/'+result.receipt.id+'/reverse','POST',{documentRevision:readDoc('owner').revision})).status,200);assert.equal(current(pendingQuick.fixture).campaign.sessions.length,0);assert(current(pendingQuick.fixture).campaign.members.some(m=>m.gangId==='pending-owned'),'Undo preserves an owner membership that existed before the battle');assert(readDoc('owner').state.campaigns[0].members.some(m=>m.gangId==='pending-owned'));
pendingQuick=pendingOwnedQuickBattle();pendingQuick.operation.after.campaign.sessions=[];pendingQuick.operation.after.gangs[0].credits=105;result=await send('owner',pendingQuick.fixture,pendingQuick.operation);assert.equal(result.status,200,result.error);assert.equal(readDoc('owner').state.campaigns[0].remoteRevision,2,'Roster-only operations also advance the owner campaign revision');assert.equal(readDoc('owner').state.gangs[0].credits,105);assert.equal((await api('owner','/campaigns/'+pendingQuick.fixture.id+'/automation/'+result.receipt.id+'/reverse','POST',{documentRevision:readDoc('owner').revision})).status,200);assert.equal(readDoc('owner').state.campaigns[0].remoteRevision,3);
pendingQuick=pendingOwnedQuickBattle({foreignCopy:true});assert.equal((await send('owner',pendingQuick.fixture,pendingQuick.operation)).status,400);assert(!current(pendingQuick.fixture).campaign.members.some(m=>m.gangId==='pending-owned'));assert.equal(counts(pendingQuick.fixture.id),0);
pendingQuick=pendingOwnedQuickBattle();failBatchAt=2;assert.equal((await send('owner',pendingQuick.fixture,pendingQuick.operation)).status,500);assert(!current(pendingQuick.fixture).campaign.members.some(m=>m.gangId==='pending-owned'));assert.equal(current(pendingQuick.fixture).campaign.sessions.length,0);assert.equal(counts(pendingQuick.fixture.id),0);
pendingQuick=pendingOwnedQuickBattle();beforeBatch=()=>sql.prepare('UPDATE documents SET revision=revision+1 WHERE user_id=?').run('owner');assert.equal((await send('owner',pendingQuick.fixture,pendingQuick.operation)).status,409);assert(!current(pendingQuick.fixture).campaign.members.some(m=>m.gangId==='pending-owned'));assert.equal(counts(pendingQuick.fixture.id),0);
console.log('Pending owner membership: quick battle, original ownership, duplicate retry, reversal, revision conflict and atomic rollback passed.');

// Native battle reports can already exist in the owner's personal document while
// the shared snapshot still predates them. Only that authoritative baseline may
// be reconciled; XP/injury mutations retain their own receipts and stale guards.
function pendingOwnedReport(){
 const fixture=setup(),doc=readDoc('owner'),report={id:'pending-report',name:'Saved challenge',challenge:true,status:'Played',winner:'same',participants:[{gangId:'same',role:'attacker'},{gangId:fixture.foreign,role:'defender'}],notes:'Keep authored report notes',privateNotes:'secret report'};
 doc.state.campaigns[0].battles=[report];doc.state.gangs[0].fighters[0].xp=61;
 sql.prepare('UPDATE documents SET state=?,revision=revision+1 WHERE user_id=?').run(JSON.stringify(doc.state),'owner');
 const snapshot=current(fixture);snapshot.gangs[0].fighters[0].xp=61;sql.prepare('UPDATE shared_campaigns SET snapshot=? WHERE id=?').run(JSON.stringify(snapshot),fixture.id);fixture.snapshot=snapshot;
 const operation=request(fixture,'pending-report-xp',()=>{});operation.before.campaign=strip(doc.state.campaigns[0]);operation.after.campaign=clone(operation.before.campaign);
 operation.after.campaign.battles[0].fighterResults=[{gangId:'same',fighterId:'fighter',xpEarned:6,injuries:[]}];
 const fighter=operation.after.gangs[0].fighters[0];fighter.xp+=6;fighter.kills=1;fighter.xpHistory.unshift({id:'pending-report-xp-entry',amount:6,battleReportId:report.id});operation.after.gangs[0].logs.unshift({id:'pending-report-log',text:'+6 XP'});
 return {fixture,operation,report};
}
