assert.equal((await api('owner','/campaigns/'+pendingReport.fixture.id+'/automation/'+pendingXpReceipt+'/reverse','POST',{documentRevision:readDoc('owner').revision})).status,200);assert.equal(readDoc('owner').state.gangs[0].fighters[0].xp,61);assert.equal(readDoc('owner').state.gangs[0].fighters[0].xpHistory.length,0);assert.equal(current(pendingReport.fixture).campaign.battles.length,1);assert.equal(current(pendingReport.fixture).campaign.battles[0].id,'pending-report');assert.equal(current(pendingReport.fixture).campaign.battles[0].fighterResults,undefined);assert.equal(readDoc('owner').state.campaigns[0].battles[0].privateNotes,'secret report');

pendingReport=pendingOwnedReport();pendingReport.operation.documentRevision=readDoc('editor').revision;assert.equal((await send('editor',pendingReport.fixture,pendingReport.operation)).status,403,'Editors cannot promote an owner-only personal report');assert.equal(current(pendingReport.fixture).campaign.battles.length,0);assert.equal(counts(pendingReport.fixture.id),0);assert.equal(readDoc('owner').state.gangs[0].fighters[0].xp,61);
