// Empty display defaults must create omitted source lists, never missing fighters.
function missingSourceLists(){
 const fixture=setup(),doc=readDoc('source'),gang=doc.state.gangs[0],fighter=gang.fighters[0];
 for(const key of ['xpHistory','injuries','effects','ooaRecords'])delete fighter[key];delete gang.logs;
 sql.prepare('UPDATE documents SET state=? WHERE user_id=?').run(JSON.stringify(doc.state),'source');return fixture;
}
function firstSourceLists(fixture,key){
 const operation=request(fixture,key,s=>{const g=s.gangs[1],fighter=g.fighters[0];fighter.xp+=6;fighter.xpHistory.push({id:'first-xp',amount:6});fighter.injuries.push({id:'first-injury',name:'Recorded injury'});fighter.effects.push({id:'first-effect',name:'Recorded effect'});g.logs.push({id:'first-log',text:'Recorded XP and injury'});});
 operation.before.gangs[1].fighters[0].ooaRecords=[];operation.after.gangs[1].fighters[0].ooaRecords=[];operation.documentRevision=readDoc('source').revision;return operation;
}
f=missingSourceLists();body=firstSourceLists(f,'source-first-lists');result=await send('source',f,body);assert.equal(result.status,200,result.error);let arrayReceipt=result.receipt.id;
for(const field of ['xpHistory','injuries','effects']){const change=result.receipt.changes.find(c=>c.target==='gang'&&c.gangId===f.foreign&&c.path.length===3&&c.path[2]===field);assert(change,field+' journals first list creation');assert.equal(change.beforeExists,false);assert.equal(change.after.length,1);assert.equal(readDoc('source').state.gangs[0].fighters[0][field].length,1);assert.equal(current(f).gangs[1].fighters[0][field].length,1);}
assert(result.receipt.changes.some(c=>c.target==='gang'&&c.path.length===1&&c.path[0]==='logs'&&!c.beforeExists));
assert.equal(readDoc('source').state.gangs[0].fighters[0].xp,11);assert.equal(Object.hasOwn(readDoc('source').state.gangs[0].fighters[0],'ooaRecords'),false,'Unchanged display defaults are not initialized');assert.equal(readDoc('source').state.gangs[0].fighters[0].privateNotes,'secret fighter');assert(!JSON.stringify(result.receipt).includes('secret'));
assert.equal((await send('source',f,body)).replayed,true);assert.equal(counts(f.id),1);
result=await api('source','/campaigns/'+f.id+'/automation/'+arrayReceipt+'/reverse','POST',{documentRevision:readDoc('source').revision});assert.equal(result.status,200,result.error);assert.equal(readDoc('source').state.gangs[0].fighters[0].xp,5);
for(const field of ['xpHistory','injuries','effects','ooaRecords'])assert.equal(Object.hasOwn(readDoc('source').state.gangs[0].fighters[0],field),false,field+' restores original absence');assert.equal(Object.hasOwn(readDoc('source').state.gangs[0],'logs'),false);
f=missingSourceLists();body=firstSourceLists(f,'stale-source-list');for(const side of ['before','after'])body[side].gangs[1].fighters[0].xpHistory.unshift({id:'unproven-old-entry',amount:2});assert.equal((await send('source',f,body)).status,409);assert.equal(readDoc('source').state.gangs[0].fighters[0].xp,5);assert.equal(counts(f.id),0);
f=missingSourceLists();body=firstSourceLists(f,'null-source-list');let arrayDoc=readDoc('source');arrayDoc.state.gangs[0].fighters[0].xpHistory=null;sql.prepare('UPDATE documents SET state=? WHERE user_id=?').run(JSON.stringify(arrayDoc.state),'source');assert.equal((await send('source',f,body)).status,409);assert.equal(readDoc('source').state.gangs[0].fighters[0].xp,5);assert.equal(counts(f.id),0);
f=missingSourceLists();body=firstSourceLists(f,'missing-source-fighter');arrayDoc=readDoc('source');arrayDoc.state.gangs[0].fighters=[];sql.prepare('UPDATE documents SET state=? WHERE user_id=?').run(JSON.stringify(arrayDoc.state),'source');assert.equal((await send('source',f,body)).status,409);assert.equal(readDoc('source').state.gangs[0].fighters.length,0);assert.equal(counts(f.id),0);
f=missingSourceLists();body=firstSourceLists(f,'later-source-history');result=await send('source',f,body);assert.equal(result.status,200,result.error);arrayReceipt=result.receipt.id;arrayDoc=readDoc('source');arrayDoc.state.gangs[0].fighters[0].xpHistory.push({id:'later-history',amount:0});assert.equal((await api('source','/document','PUT',{revision:arrayDoc.revision,state:arrayDoc.state})).status,200);assert.equal((await api('source','/campaigns/'+f.id+'/automation/'+arrayReceipt+'/reverse','POST',{documentRevision:readDoc('source').revision})).status,409);assert.equal(readDoc('source').state.gangs[0].fighters[0].xp,11);assert.equal(readDoc('source').state.gangs[0].fighters[0].xpHistory.length,2);
